package com.company.aiinterview.ai.controller; import com.company.aiinterview.ai.dto.request.*; import com.company.aiinterview.ai.dto.response.*; import com.company.aiinterview.ai.service.*; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/ai") @RequiredArgsConstructor public class GeminiController { private final GeminiQuestionService q; private final GeminiEvaluationService e; private final SkillExtractionService s; @PostMapping("/question") public GenerateQuestionResponseDto question(@RequestBody GenerateQuestionRequestDto r){ return q.generateQuestion(r);} @PostMapping("/evaluate") public EvaluateAnswerResponseDto eval(@RequestBody EvaluateAnswerRequestDto r){ return e.evaluateAnswer(r);} @PostMapping("/extract-skills") public ExtractSkillsResponseDto extract(@RequestBody ExtractSkillsRequestDto r){ return s.extractSkills(r);} }
